[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/contact/MessageStore.java", "content": "package com.example.contact;

import java.util.ArrayList;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * The messages that have been sent, newest first.
 * <p>
 * The messages live in the Vaadin session, so they outlive a single visit to
 * the contact view without being written anywhere.
 */
public final class MessageStore {

    private static final String ATTRIBUTE = MessageStore.class.getName();

    private MessageStore() {
    }

    /** The messages sent so far, newest first. */
    public static List<Message> messages() {
        return List.copyOf(sent());
    }

    /** Adds a message as the newest one. */
    public static void add(Message message) {
        sent().add(0, message);
    }

    @SuppressWarnings("unchecked")
    private static List<Message> sent() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            // No session to remember anything in (should not happen in a view).
            return new ArrayList<>();
        }
        List<Message> messages = (List<Message>) session.getAttribute(ATTRIBUTE);
        if (messages == null) {
            messages = new ArrayList<>();
            session.setAttribute(ATTRIBUTE, messages);
        }
        return messages;
    }
}
