+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Message> grid() {
+        return $(Grid.class).single();
+    }
+
+    private void fillIn(String nameValue, String emailValue, String phoneValue,
+            String messageValue) {
+        test(name).setValue(nameValue);
+        test(email).setValue(emailValue);
+        test(phone).setValue(phoneValue);
+        test(message).setValue(messageValue);
+    }
+
+    @Test
+    void formIsEmptyAndSendIsEnabled() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue($(RouterLink.class).withText("About").exists());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertTrue(send.isEnabled());
+        assertFalse(name.isInvalid());
+    }
+
+    @Test
+    void aboutLinkNavigatesWithoutLeavingTheApplication() {
+        assertSame(AboutView.class,
+                test($(RouterLink.class).withText("About").single()).navigate().getClass());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyFormReportsEveryFailure() {
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertFalse($(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void invalidEmailIsReported() {
+        fillIn("Alice", "not-an-email", "", "Hello");
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertEquals(0, test(grid()).size());
+        assertEquals("Alice", name.getValue());
+    }
+
+    @Test
+    void phoneAloneIsEnough() {
+        fillIn("Alice", "", "+358 40 123 4567", "Hello");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void emailAloneIsEnough() {
+        fillIn("Alice", "alice@example.com", "", "Hello");
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessageIsReported() {
+        fillIn("Alice", "alice@example.com", "", "x".repeat(501));
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void fiveHundredCharacterMessageIsSent() {
+        fillIn("Alice", "alice@example.com", "", "x".repeat(500));
+        test(send).click();
+
+        assertFalse(message.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void sendingClearsTheFormAndShowsTheMessage() {
+        fillIn("Alice", "alice@example.com", "0401234567", "Hello there");
+        test(send).click();
+
+        assertTrue(test($(Notification.class).first()).getText().contains("Message sent"));
+        assertEquals(1, test(grid()).size());
+        assertEquals("Alice", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", phone.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(name.isInvalid());
+        assertTrue(name.getErrorMessage() == null || name.getErrorMessage().isEmpty());
+
+        assertFalse(send.isEnabled(), "Send is disabled right after sending");
+        test(name).setValue("B");
+        assertTrue(send.isEnabled(), "Editing enables Send again");
+    }
+
+    @Test
+    void newestMessageIsFirst() {
+        fillIn("Alice", "alice@example.com", "", "First");
+        test(send).click();
+        fillIn("Bob", "bob@example.com", "", "Second");
+        test(send).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Bob", test(grid()).getRow(0).name());
+        assertEquals("Alice", test(grid()).getRow(1).name());
+    }
+
+    @Test
+    void enterSends() {
+        fillIn("Alice", "alice@example.com", "", "Hello");
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("", name.getValue());
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingTheView() {
+        fillIn("Alice", "alice@example.com", "", "Hello");
+        test(send).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(1, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void leavingWithAnEmptyFormIsNotInterrupted() {
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertSame(AboutView.class, getCurrentView().getClass());
+    }
+
+    @Test
+    void keepEditingStaysInTheView() {
+        test(name).setValue("Alice");
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).exists());
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertSame(ContactView.class, getCurrentView().getClass());
+        assertEquals("Alice", name.getValue());
+    }
+
+    @Test
+    void discardLeavesTheView() {
+        test(message).setValue("Something typed");
+        test($(RouterLink.class).withText("About").single()).click();
+
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertSame(AboutView.class, getCurrentView().getClass());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void theQuestionIsAskedAgainOnTheNextAttempt() {
+        test(name).setValue("Alice");
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        test($(RouterLink.class).withText("About").single()).click();
+        assertTrue($(Dialog.class).exists());
+        test($(Button.class).withText("Discard").single()).click();
+        assertSame(AboutView.class, getCurrentView().getClass());
+    }
+
+    @Test
+    void leavingIsNotInterruptedAfterSending() {
+        fillIn("Alice", "alice@example.com", "", "Hello");
+        test(send).click();
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertSame(AboutView.class, getCurrentView().getClass());
+    }
+
+    @Test
+    void programmaticNavigationAlsoAsksFirst() {
+        test(phone).setValue("0401234567");
+        com.vaadin.flow.component.UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue($(Dialog.class).exists());
+        assertSame(ContactView.class, getCurrentView().getClass());
+    }
+}
